# Look for local pattern - maybe it's about connectivity or isolated pixels vs clusters
# Check if 5s that become 7 in demo 1 are connected differently

demo_in_1 = parse_grid(demo_in_1_str)
demo_out_1 = parse_grid(demo_out_1_str)

# Find where 5s map to 0 vs 7
five_to_zero = []
five_to_seven = []

for r in range(len(demo_in_1)):
    for c in range(len(demo_in_1[0])):
        if demo_in_1[r][c] == 5:
            if demo_out_1[r][c] == 0:
                    five_to_zero.append((r,c))
            else:  # == 7
                five_to_seven.append((r,c))

print(f"Number of 5s: 293")
print(f"5s → 0: {len(five_to_zero)}")
print(f"5s → 7: {len(five_to_seven)}")

# Check if 5s → 7 are connected or form a pattern
def get_neighbors(r, c, rows, cols):
    neigh = []
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:  # 4-connectivity
        nr, nc = r+dr, c+dc
        if 0 <= nr < rows and 0 <= nc < cols:
            neigh.append((nr,nc))
    return neigh

# Count how many same-value neighbors each 5 has
neighbor_counts = {}
for r, c in five_to_seven:
    count = sum(1 for nr, nc in get_neighbors(r, c, len(demo_in_1), len(demo_in_1[0])) 
               if demo_in_1[nr][nc] == 5)
    neighbor_counts[count] = neighbor_counts.get(count, 0) + 1

print("\nDistribution of same-valued neighbors for 5s→7:")
for k,v in sorted(neighbor_counts.items()):
    print(f"  {k} neighbors: {v} cells")

# Check for 5s→0
neighbor_counts_zero = {}
for r, c in five_to_zero:
    count = sum(1 for nr, nc in get_neighbors(r, c, len(demo_in_1), len(demo_in_1[0])) 
               if demo_in_1[nr][nc] == 5)
    neighbor_counts_zero[count] = neighbor_counts_zero.get(count, 0) + 1

print("\nDistribution of same-valued neighbors for 5s→0:")
for k,v in sorted(neighbor_counts_zero.items()):
    print(f"  {k} neighbors: {v} cells")

# Find all connected components of 5s and see what their outcomes are
from collections import deque, defaultdict

def get_all_connected_components(r, c, grid, target_val):
    comp = []
    visited = set()
    queue = deque([(r,c)])
    while queue:
        curr_r, curr_c = queue.popleft()
        if (curr_r, curr_c) in visited:
            continue
        visited.add((curr_r, curr_c))
        comp.append((curr_r, curr_c))
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = curr_r + dr, curr_c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == target_val and (nr, nc) not in visited:
                    queue.append((nr, nc))
    return comp

demo_in = parse_grid(demo_in_1_str)
demo_out = parse_grid(demo_out_1_str)
rows, cols = len(demo_in), len(demo_in[0])

visited_global = set()
component_id = 0
comp_map = {}  # maps each cell to its component id

for r in range(rows):
    for c in range(cols):
        if demo_in[r][c] == 5 and (r, c) not in visited_global:
            comp = get_all_connected_components(r, c, demo_in, 5)
            comp_id += 1
            for cell in comp:
                comp_map[cell] = comp_id

num_components = comp_id
print(f"\nNumber of connected components of 5s in demo 1: {num_components}")
print(f"Component sizes:")

comp_cells = defaultdict(list)
for cell, cid in comp_map.items():
    comp_cells[cid].append(cell)

for cid in sorted(comp_cells.keys()):
    print(f"  Comp {cid}: {len(comp_cells[cid])} cells")

# Now check outcomes per component
comp_outcomes = {}
for cid in range(1, num_components+1):
    cells_in_comp = comp_cells[cid]
    outcomes = set()
    for r, c in cells_in_comp:
        outcomes.add(demo_out[r][c])
    comp_outcomes[cid] = len(cells_in_comp), outcomes

print("\nComponent outcomes (size, unique outputs):")
for cid in sorted(comp_outcomes.keys()):
